files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #ECECEC;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #000000;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #1a5dc2;
  --vt-accent-on-deep: #1a5dc2;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink-soft);
  background: var(--vt-surface);
}

/* Navigation */
.nav {
  background: var(--vt-surface);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 20px 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-block;
  text-decoration: none;
}

.brand {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--vt-accent);
}

.brand strong {
  display: block;
  font-size: 0.8rem;
  color: var(--vt-ink-soft);
  font-weight: 600;
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  text-decoration: none;
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 1rem;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  margin-top: 94px; /* offset for fixed nav */
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 580px;
  -webkit-overflow-scrolling: touch;
}

.slide {
  flex: 0 0 100%;
  height: 100%;
  scroll-snap-align: start;
  position: relative;
}

.slideImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroCard {
  background: var(--vt-surface);
  position: absolute;
  bottom: 0;
  right: 0;
  padding: 2rem 2.5rem;
  width: 50%;
  z-index: 2;
}

.kicker {
  color: var(--vt-accent);
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.heroTitle {
  color: var(--vt-ink);
  font-size: 3rem;
  font-weight: 700;
  margin: 0 0 1rem;
}

.heroText {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.cta {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  padding: 0 30px;
  line-height: 40px;
  text-transform: uppercase;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s;
}

.cta:hover {
  background: var(--vt-line);
  color: var(--vt-accent-ink);
}

.phone {
  color: var(--vt-ink-soft);
  font-weight: 600;
  text-decoration: none;
}

/* Sections */
.section {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.sectionTitle {
  color: var(--vt-ink);
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: 2rem;
}

.center {
  text-align: center;
}

/* About */
.aboutGrid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 3rem;
  align-items: center;
}

.aboutText {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  line-height: 1.7;
  margin-bottom: 1rem;
}

.storyFigure {
  margin: 0;
}

.storyImg {
  width: 100%;
  height: auto;
  border-radius: 4px;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.1);
}

/* Gallery */
.gallery {
  padding: 0;
}

.galleryGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.galleryItem {
  margin: 0;
}

.galleryImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Timeline */
.timeline {
  position: relative;
  padding: 1rem 0;
}

.timeline::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  width: 100%;
  margin: 2rem 0;
}

.timelineIcon {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.iconNumber {
  color: var(--vt-accent);
  font-size: 2rem;
  font-weight: 700;
}

.timelineCard {
  background: var(--vt-surface);
  box-shadow: 0 0 20px rgba(0,0,0,0.1);
  border-radius: 4px;
  width: 45%;
  overflow: hidden;
}

.timelineNode.odd .timelineCard {
  margin-right: 55%;
}

.timelineNode.even .timelineCard {
  margin-left: 55%;
}

.timelineTitle {
  background: var(--vt-ink);
  color: var(--vt-surface);
  padding: 10px 20px;
  margin: 0;
  font-size: 1.25rem;
}

.timelineDesc {
  padding: 15px 20px;
  color: var(--vt-ink-soft);
  margin: 0;
}

.timelineDuration {
  padding: 0 20px 15px;
  color: var(--vt-accent-ink);
  font-weight: 600;
  margin: 0;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 7rem 0 2rem;
}

.footerGrid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 30px;
}

.footerTitle {
  color: var(--vt-ink);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.hours {
  color: var(--vt-ink-soft);
  white-space: pre-line;
  line-height: 1.6;
}

.socialLinks {
  display: flex;
  gap: 15px;
}

.copyright {
  text-align: center;
  color: var(--vt-ink-soft);
  margin-top: 3rem;
  font-size: 0.9rem;
}

/* Focus styles */
.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Responsive */
@media (max-width: 991px) {
  .hero {
    margin-top: 74px;
  }
  .heroTrack {
    height: auto;
  }
  .heroCard {
    position: relative;
    width: auto;
    margin-bottom: -50px;
    padding: 2rem;
    bottom: 50px;
  }
  .aboutGrid {
    grid-template-columns: 1fr;
  }
  .timelineCard {
    width: 100%;
  }
  .timelineNode.odd .timelineCard,
  .timelineNode.even .timelineCard {
    margin: 0;
  }
  .timelineIcon {
    left: 30px;
    transform: none;
  }
  .timeline::before {
    left: 30px;
  }
  .footerGrid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 767px) {
  .navIn {
    flex-direction: column;
    gap: 10px;
  }
  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
    gap: 1rem;
  }
  .heroCard {
    padding: 1.5rem;
  }
  .heroTitle {
    font-size: 2rem;
  }
  .section {
    padding: 5rem 0;
  }
  .galleryGrid {
    grid-template-columns: 1fr;
  }
  .footerGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .heroLinks .cta {
    font-size: 0.8rem;
    line-height: 30px;
    padding: 0 20px;
  }
  .timelineIcon {
    width: 60px;
    height: 60px;
  }
  .iconNumber {
    font-size: 1.5rem;
  }
  .timeline::before {
    left: 25px;
  }
  .timelineIcon {
    left: 25px;
  }
}
